window.EB_DINFO={"bagerhat":{"en":"Bagerhat","div":"khulna","tag":"A mosque city of brick and the mangrove frontier","lede":"Bagerhat holds the 15th-century mosque city of Khan Jahan Ali, a UNESCO World Heritage Site of brick domes among ponds and palms. To the south, Mongla and Sarankhola open onto the eastern Sundarbans, with Karamjal, Katka and Kochikhali on most itineraries.","img":"2c948193","mx":1920,"glance":[],"known":["Sixty Dome Mosque","Khan Jahan Ali's tomb","Karamjal","Katka and Kochikhali","Shrimp farming"],"trips":["sundarbans-and-bagerhat"],"stay":[["Budget hotel","৳800–1,800"],["Good hotel","৳2,500–3,800"],["Upscale / resort","No data"]],"peak":"Peak season: Sundarbans season (September–March) fills Mongla's few hotels on weekends.","order":["sixty-dome-mosque","khan-jahan-ali-tomb","karamjal","katka-kochikhali","nine-dome-mosque","singair-mosque","dublar-char","bagerhat-bagda-chingri","mongla-sundarbans-crab","chunakhola-mosque","kodla-math","bibi-begni-mosque","dublar-char-rash-mela"]},"bandarban":{"en":"Bandarban","div":"chattogram","tag":"Cloud-wrapped peaks, crater lakes and Marma villages","lede":"Bandarban holds the highest hills in Bangladesh, cut by the Sangu river and dotted with Marma, Bawm, Mro and other indigenous villages. Roads climb to viewpoints above the clouds, while longer treks reach a crater lake and remote waterfalls. Security rules here change often, so plan with current permits and advisories in hand.","img":"0165537f","mx":1920,"glance":[],"known":["Nilgiri and Nilachal viewpoints","Boga Lake","Nafakhum waterfall","Golden Temple","Sangrai water festival"],"trips":["coxs-bazar-and-bandarban"],"stay":[["Budget hotel","৳600–2,000"],["Good hotel","৳2,000–4,500"],["Upscale / resort","৳6,000–15,000"]],"peak":"Peak season: During Eid and winter holidays hotels and resorts in town, Meghla and Nilachal are fully booked.","order":["nilgiri-bandarban","nilachal-bandarban","boga-lake","nafakhum-waterfall","bandarban-golden-temple","shoilo-propat","keokradong","mundi","bandarban-bashkorol","bandarban-nappi","bandarban-tojah-laksu","bandarban-hill-fruits","debotakhum","rijuk-waterfall","amiakhum-waterfall","sangrai-festival"]},"barguna":{"en":"Barguna","div":"barishal","tag":"Quiet beaches, coastal forest and fishing harbours","lede":"Barguna lies between the Bishkhali and Payra rivers where they open to the Bay of Bengal. It has the uncrowded Shuvo Sondha beach, the Tengragiri mangrove forest, Rakhine villages in Taltoli and the busy fishing port of Patharghata, plus a Mughal-era mosque inland.","img":"4f3fa04e","mx":1920,"glance":[],"known":["Shuvo Sondha beach","Tengragiri forest","Bibi Chini Mosque","Patharghata fishing port"],"trips":[],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["shuvo-sondha-beach","tengragiri-forest","bibi-chini-mosque","taltoli-rakhine-temple","laldia-beach","patharghata-ilish","barguna-shutki","haringhata-forest","bihanga-island","rakhine-water-festival"]},"barishal":{"en":"Barishal","div":"barishal","tag":"River city of launches, ilish and water lilies","lede":"Barishal is the capital of Bangladesh's river country, reached by overnight launches from Dhaka down the Meghna and Kirtankhola. Around the city are a grand modern mosque, an old royal tank and wetlands that turn red with water lilies, while the region's ilish and Gournadi doi are known nationwide.","img":"06795f85","mx":1920,"glance":[],"known":["Overnight launch journeys","Guthia Mosque","Durgasagar","Ilish","Gournadi doi"],"trips":[],"stay":[["Budget hotel","৳800–2,500"],["Good hotel","৳2,500–6,000"],["Upscale / resort","৳6,000–15,000"]],"peak":"","order":["guthia-mosque","durgasagar-dighi","oxford-mission-church","bibir-pukur","mahilara-sarkar-math","sher-e-bangla-museum-chakhar","qasba-mosque-gournadi","sugandha-shaktipeeth","barishal-ilish","gournadi-doi","barishal-molida","satla-shapla-bil","lakutia-zamindar-bari","karapur-miah-bari-mosque","dhaka-barishal-launch"]},"bhola":{"en":"Bhola","div":"barishal","tag":"Bangladesh's largest island, buffalo curd and Meghna hilsa","lede":"Bhola is the country's largest island, wrapped by the Meghna and Tentulia where they meet the sea. Its southern chars hold mangrove forests, spotted deer and empty beaches, while herds of buffalo graze the islands and supply the district's famous curd.","img":"7ce4c5f4","mx":1920,"glance":[],"known":["Mohisher doi","Char Kukri Mukri","Monpura island","Meghna ilish"],"trips":[],"stay":[["Budget hotel","৳500–2,000"],["Good hotel","৳2,000–3,500"],["Upscale / resort","No data"]],"peak":"","order":["char-kukri-mukri","monpura-island","jacob-tower","bhola-independence-museum","mostafa-kamal-memorial-museum","bhola-mohisher-doi","bhola-meghna-ilish","tarua-beach","bhola-buffalo-bathan"]},"bogura":{"en":"Bogura","div":"rajshahi","tag":"Ancient Pundranagar and the country's famous sweet doi","lede":"Bogura is the gateway to Mahasthangarh, the ruins of ancient Pundranagar and one of the oldest urban sites in Bangladesh. It is also the home of the creamy, sweetened doi that people buy by the clay pot all over the country.","img":"52803b8e","mx":1920,"glance":[],"known":["Mahasthangarh","Bogura doi","Behula's Bashor Ghor","Kotkoti sweets"],"trips":["north-bengal-heritage-by-bike"],"stay":[["Budget hotel","৳1,000–2,500"],["Good hotel","৳3,000–7,000"],["Upscale / resort","৳8,000–15,000"]],"peak":"","order":["mahasthangarh","gokul-medh","kherua-mosque","bogura-nawab-palace-museum","sariakandi-jamuna-ghat","bogura-doi","mahasthan-kotkoti","bogura-laccha-semai","bogura-aloo-ghati","sariakandi-red-chilli","vasu-bihar","govinda-bhita","poradaha-mela"]},"brahmanbaria":{"en":"Brahmanbaria","div":"chattogram","tag":"Titas river country, classical music and chhanamukhi","lede":"Brahmanbaria lies along the Titas river on the eastern edge of the Meghna basin, close to the Tripura border. It is the birthplace of the great musician Ustad Alauddin Khan and the setting of the classic novel 'A River Called Titas'. Visitors come for river life, old temples and mosques, and a crunchy sweet found nowhere else.","img":"11173ea0","mx":1920,"glance":[],"known":["Chhanamukhi","Titas river","Ustad Alauddin Khan","Kalbhairab temple","Arifail mosque"],"trips":[],"stay":[["Budget hotel","৳800–2,000"],["Good hotel","৳2,000–4,000"],["Upscale / resort","No data"]],"peak":"","order":["kalbhairab-temple","titas-river","arifail-mosque","haripur-zamindar-bari","kharampur-mazar-sharif","brahmanbaria-chhanamukhi","titas-river-fish","sarail-hatirpul","ulchapara-mosque","ustad-alauddin-khan-heritage"]},"chandpur":{"en":"Chandpur","div":"chattogram","tag":"Where three rivers meet and the hilsa runs","lede":"Chandpur sits where the Padma and Meghna merge, a meeting of huge rivers that locals call the three-river confluence. It is the country's best-known hilsa town, with fish landing at the ghats every morning in season. Launches from Dhaka make the trip a pleasant river journey in itself.","img":"62ce2e0a","mx":1920,"glance":[],"known":["Hilsa fish","Padma–Meghna confluence","Molehead at Boro Station","River launches","Hajiganj mosque"],"trips":[],"stay":[["Budget hotel","৳800–2,000"],["Good hotel","৳2,000–4,000"],["Upscale / resort","No data"]],"peak":"","order":["chandpur-molehead","boro-station-fish-ghat","hajiganj-boro-mosque","rupsha-zamindar-bari","chandpur-hilsa","ilish-dim-bhuna","chandpur-one-minute-ice-cream","chandpur-meghna-char","lohagar-math","chandpur-hilsa-fishing-life"]},"chapainawabganj":{"en":"Chapainawabganj","div":"rajshahi","tag":"Mango country and the old mosques of Gaur","lede":"Chapainawabganj sits in the far west of Bangladesh, where endless mango orchards meet the Bangladeshi side of the medieval capital of Gaur. It is also the home of Gombhira, a witty folk song form, and of the humble but beloved kalai roti.","img":"84abb011","mx":1920,"glance":[],"known":["Mangoes","Choto Sona Mosque","Gombhira songs","Kalai roti"],"trips":[],"stay":[["Budget hotel","৳700–1,800"],["Good hotel","৳1,800–2,800"],["Upscale / resort","No data"]],"peak":"","order":["choto-sona-mosque","darasbari-mosque","tahkhana-shah-niamatullah","kotwali-darwaza","kansat-zamindar-bari","kansat-mango-market","kalai-roti","shibganj-amshotto","shibganj-chomchom","khania-dighi-mosque","dhaniachak-mosque","nawda-buruj","gombhira"]},"chattogram":{"en":"Chattogram","div":"chattogram","tag":"Port city, green hills and the biggest feasts in Bengal","lede":"Bangladesh's main port city sits where the Karnaphuli River meets the Bay of Bengal, with hills rolling right into town. Come for sea breezes at Patenga, temple-topped hills at Sitakunda and a food culture built around generous beef feasts.","img":"03923b39","mx":1920,"glance":[],"known":["Mezban feasts","Kala bhuna","Patenga sea beach","Sitakunda hills","Jabbarer Boli Khela"],"trips":[],"stay":[["Budget hotel","৳1,000–2,500"],["Good hotel","৳3,000–6,000"],["Upscale / resort","৳9,000–14,000"]],"peak":"","order":["patenga-sea-beach","foys-lake","chandranath-hill-sitakunda","bayazid-bostami-shrine","parki-beach","mohamaya-lake","chittagong-war-cemetery","sitakunda-eco-park","ethnological-museum-chattogram","anderkilla-shahi-jame-mosque","mezban","kala-bhuna","chattogram-durus-kura","chattogram-bela-biscuit","chattogram-shutki-asadganj","guliakhali-sea-beach","khoiyachora-waterfall","napittachora-trail","baroiyadhala-national-park","jabbarer-boli-khela"]},"chuadanga":{"en":"Chuadanga","div":"khulna","tag":"Mango orchards, indigo ruins and an old distillery","lede":"Chuadanga is a flat, fertile border district of mango orchards, vegetable fields and date palms along the Mathabhanga and Bhairab rivers. Darshana's sugar mill and distillery date to colonial times, and Karpashdanga holds indigo-era ruins and memories of poet Kazi Nazrul Islam.","img":"8dc21621","mx":1920,"glance":[],"known":["Mangoes","Darshana sugar mill","Karpashdanga Nilkuthi","Date palm gur"],"trips":[],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["darshana","mathabhanga-riverfront","chuadanga-bara-masjid","aat-kobor","gholdari-shahi-mosque","chuadanga-mango","chuadanga-khejur-gur","karpashdanga","natudah-hazarduari-school","thakurpur-jame-mosque","chuadanga-indigo-heritage"]},"coxs-bazar":{"en":"Cox's Bazar","div":"chattogram","tag":"The long sea beach, coral island and fishing villages","lede":"Cox's Bazar is home to one of the longest natural sand beaches in the world, running south toward Teknaf along the Bay of Bengal. Beyond the hotel strip are hills meeting the sea at Himchari, rocky shores at Inani, island temples at Maheshkhali and the country's only coral island, St. Martin's.","img":"77151417","mx":1920,"glance":[],"known":["Long sandy sea beach","St. Martin's Island","Marine Drive","Fresh seafood","Dried fish"],"trips":["coxs-bazar-and-bandarban","st-martins-island"],"stay":[["Budget hotel","৳1,000–2,500"],["Good hotel","৳2,500–5,500"],["Upscale / resort","৳6,500–15,000"]],"peak":"Peak season: December–January, Fridays and Eid holidays fill most of the 500+ hotels and push rents up; in the June–September off-season hotels often give up to 50% off.","order":["coxs-bazar-beach","himchari","inani-beach","st-martins-island","maheshkhali-island","coxs-bazar-teknaf-marine-drive","ramkot-banashram-ramu","dulahazra-safari-park","coxs-bazar-seafood-fry","nazirartek-shutki","coxs-bazar-loitta-fry","maheshkhali-paan","coxs-bazar-rakhine-food","sonadia-island","shah-porir-dwip","kutubdia-island","ramu-probarona-fanush"]},"cumilla":{"en":"Cumilla","div":"chattogram","tag":"Buddhist ruins, roshmalai and handwoven khadi","lede":"Cumilla sits on the Dhaka–Chattogram highway, and the Lalmai–Mainamati hills just west of town hide the remains of Buddhist monasteries more than a thousand years old. The town is also known for its old ponds, its handwoven khadi cloth and a famous sweet, roshmalai.","img":"2e598e7c","mx":1920,"glance":[],"known":["Shalban Vihara","Roshmalai","Khadi cloth","Mainamati War Cemetery","Dharmasagar Dighi"],"trips":[],"stay":[["Budget hotel","৳1,000–2,500"],["Good hotel","৳2,500–6,000"],["Upscale / resort","No data"]],"peak":"","order":["shalban-vihara","maynamati-war-cemetery","dharmasagar-dighi","mainamati-museum","shah-shuja-mosque-cumilla","cumilla-jagannath-temple","cumilla-roshmalai","lalmai-jackfruit","rupban-mura","lalmai-chandi-temple","ananda-vihara","cumilla-khadi","bijoypur-pottery"]},"dhaka":{"en":"Dhaka","div":"dhaka","tag":"Mughal forts, river ghats and the lanes of Old Dhaka","lede":"Bangladesh's capital is loud, crowded and endlessly absorbing. Behind the traffic lies a 400-year-old Mughal and colonial city, with riverside palaces, mosaic mosques and the best street food in the country.","img":"d3a647c7","mx":1920,"glance":[],"known":["Old Dhaka heritage","Sadarghat river port","Biryani and bakarkhani","Shakrain kite festival"],"trips":["dhaka-old-town-and-sonargaon"],"stay":[["Budget hotel","৳1,500–5,000"],["Good hotel","৳5,000–12,000"],["Upscale / resort","৳12,000–20,000"]],"peak":"","order":["lalbagh-fort","ahsan-manzil","star-mosque-dhaka","sadarghat-buriganga","jatiya-sangsad-bhaban","dhakeshwari-temple","bangladesh-national-museum","national-martyrs-memorial-savar","liberation-war-museum-dhaka","hussaini-dalan","dhaka-old-town-biryani","dhaka-bakarkhani","chawkbazar-iftar-bazar","beauty-lassi-falooda","geneva-camp-kabab-chaap","dhaka-fuchka-chotpoti","armenian-church-dhaka","baldha-garden","rose-garden-palace","bara-katra","shakrain-kite-festival","mangal-shobhajatra"]},"dinajpur":{"en":"Dinajpur","div":"rangpur","tag":"Terracotta temples, great ponds and litchi orchards","lede":"Dinajpur is home to Kantajew Temple, the finest terracotta temple in Bangladesh, and to Ramsagar, a vast 18th-century pond turned national park. Its fertile land grows fragrant Kataribhog rice and the litchis that sell across the country every summer.","img":"1defc3f2","mx":1920,"glance":[],"known":["Kantajew Temple","Ramsagar","Dinajpur litchi","Kataribhog rice","Dinajpur Rajbari"],"trips":["north-bengal-heritage-by-bike"],"stay":[["Budget hotel","৳500–1,000"],["Good hotel","৳3,500–4,000"],["Upscale / resort","No data"]],"peak":"","order":["kantajew-temple","ramsagar","dinajpur-rajbari","swapnapuri-amusement-park","singra-national-park","nawabganj-national-park","sura-mosque","dinajpur-museum","dinajpur-litchi","kataribhog-rice","dinajpur-papad","nayabad-mosque","sitakot-vihara","aokora-mosque","kantajew-rash-mela"]},"faridpur":{"en":"Faridpur","div":"dhaka","tag":"Jasimuddin's village, jute fields and the Padma","lede":"Faridpur is the home district of Palli Kabi Jasimuddin, the poet of rural Bengal, and the landscape of his poems is still here: jute fields, river villages and the Kumar and Padma rivers. It also holds medieval mosques and an unusual Mughal-era temple tower.","img":"e2f6d170","mx":1920,"glance":[],"known":["Palli Kabi Jasimuddin","Mathurapur Deul","Jute","Malaikari sweet"],"trips":[],"stay":[["Budget hotel","৳800–2,000"],["Good hotel","৳2,000–4,000"],["Upscale / resort","No data"]],"peak":"","order":["jasimuddin-house-ambikapur","mathurapur-deul","satoir-mosque","sri-angan-faridpur","faridpur-malaikari","faridpur-padma-ilish","boalmari-ilish-peti","faridpur-khejur-gur","faridpur-padma-chars","pathrail-mosque-bhanga","munshi-abdur-rouf-museum","jasimuddin-mela","faridpur-jute"]},"feni":{"en":"Feni","div":"chattogram","tag":"Big dighis, a river dam and Khondol sweets","lede":"Feni is a compact district between Cumilla and Chattogram, crossed by the main highway. Its landscape is flat and green, broken by large old ponds and the wide reservoir of the Muhuri Project near the coast. It is also proud of its sweets and of a language martyr born in its villages.","img":"df319520","mx":1920,"glance":[],"known":["Muhuri Project","Bijoy Singh Dighi","Khondoler mishti","Buffalo curd","Language martyr Abdus Salam"],"trips":[],"stay":[["Budget hotel","৳800–2,000"],["Good hotel","৳2,000–4,000"],["Upscale / resort","No data"]],"peak":"","order":["muhuri-project","bijoy-singh-dighi","rajajhir-dighi","shamsher-gazi-fort","khondoler-mishti","sonagazi-char-doi","chandgazi-bhuiyan-mosque","shilua-stone","sat-math-chhagalnaiya","bhasha-shaheed-salam-memorial"]},"gaibandha":{"en":"Gaibandha","div":"rangpur","tag":"Brahmaputra chars, river embankments and rosh monjori","lede":"Gaibandha lies between the Brahmaputra and the Teesta, with sandy river islands (chars) where life follows the floods. It is best known for rosh monjori, a rich milk sweet, and for the riverside embankment at Balashi Ghat.","img":"4c0aee10","mx":1920,"glance":[],"known":["Rosh monjori","Balashi Ghat","Brahmaputra chars","Phulchhari chillies"],"trips":[],"stay":[["Budget hotel","৳1,000–2,500"],["Good hotel","৳2,500–5,000"],["Upscale / resort","No data"]],"peak":"","order":["balashi-ghat","bardhankuthi","fulchhari-chars","jamalpur-shahi-mosque-gaibandha","gaibandha-rosh-monjori","phulchhari-chilli","gaibandha-atta-dal","friendship-centre-gaibandha","naldanga-zamindar-bari","raja-birat-mound","gaibandha-char-life"]},"gazipur":{"en":"Gazipur","div":"dhaka","tag":"Sal forests, jackfruit orchards and the Bhawal estate","lede":"Just north of Dhaka, Gazipur mixes fast-growing factory towns with patches of old sal forest that once belonged to the Bhawal zamindars. It is the easiest green escape from the capital, with forest walks, a safari park and roadside jackfruit stalls.","img":"75c6138f","mx":1920,"glance":[],"known":["Bhawal sal forest","Safari park at Sreepur","Jackfruit","Bishwa Ijtema at Tongi"],"trips":[],"stay":[["Budget hotel","৳1,000–2,500"],["Good hotel","৳2,500–8,600"],["Upscale / resort","৳10,000–25,000"]],"peak":"Peak season: Resorts charge more on Friday–Saturday and public holidays; weekday deals are common.","order":["bhawal-national-park","gazipur-safari-park","bhawal-rajbari","nagari-church","gazipur-jackfruit","gazipur-lychee","nuhash-polli","bhawal-raj-shmashaneshwari","baliadi-zamindar-bari","isa-khan-tomb-bakhtarpur","bishwa-ijtema-tongi"]},"gopalganj":{"en":"Gopalganj","div":"dhaka","tag":"Wetlands, floating gardens and the Madhumati","lede":"Gopalganj is low, watery country on the Madhumati river, laced with beels and canals. Farmers here grow vegetables on floating beds of water hyacinth, the Matua faith holds its great annual gathering at Orakandi, and Tungipara draws visitors to the grave of Sheikh Mujibur Rahman.","img":"2e2a5c55","mx":1920,"glance":[],"known":["Floating gardens","Tungipara","Orakandi Matua festival","Rasgolla"],"trips":[],"stay":[["Budget hotel","৳700–1,500"],["Good hotel","৳1,300–2,000"],["Upscale / resort","No data"]],"peak":"","order":["tungipara-mausoleum","orakandi-thakurbari","chanda-beel","gopalganj-court-mosque","gopalganj-rasgolla","gopalganj-beel-fish","kashiani-rasmalai","kotalipara-floating-gardens","ulpur-zamindar-bari","orakandi-baruni-snan"]},"habiganj":{"en":"Habiganj","div":"sylhet","tag":"Forest trails, tea estates and wide haor waters","lede":"Habiganj has two faces: in the east, low hills covered with tea gardens and some of the country's finest remaining hill forest; in the west, the great haor wetlands around Baniachong. It is a quieter alternative to Srimangal for forest walks and birdwatching.","img":"ce459eac","mx":1920,"glance":[],"known":["Satchari National Park","Rema-Kalenga sanctuary","Tea gardens","Baniachong haor","Teliapara memorial"],"trips":[],"stay":[["Budget hotel","৳800–2,000"],["Good hotel","৳2,000–5,000"],["Upscale / resort","৳11,500–20,000"]],"peak":"","order":["satchari-national-park","rema-kalenga-wildlife-sanctuary","teliapara-tea-estate","baniachong-sagar-dighi","shankarpasha-shahi-mosque","habiganj-rosogolla","habiganj-haor-fish","bithangal-akhra","mashajan-dighi","tea-workers-phagua"]},"jamalpur":{"en":"Jamalpur","div":"mymensingh","tag":"Nakshi kantha, para sandesh and the Garo foothills","lede":"Jamalpur lies between the Jamuna and the Old Brahmaputra, stretching north to the foothills of the Garo Hills. It is best known for nakshi kantha embroidery, the para sandesh of Sarishabari, and quiet hill spots like Lauchapra.","img":"d6720b44","mx":1920,"glance":[],"known":["Nakshi kantha","Sarishabari para sandesh","Lauchapra hills","Jamuna chars"],"trips":[],"stay":[["Budget hotel","৳800–2,000"],["Good hotel","৳2,000–4,000"],["Upscale / resort","No data"]],"peak":"","order":["lauchapra","gandhi-ashram-jamalpur","bahadurabad-ghat","dayamoyee-temple-jamalpur","masjid-e-noor-bakshiganj","sarishabari-para-sandesh","jamalpur-char-peanuts","jamalpur-burimar-mishti","jamalpur-chhanar-polao","jamalpur-jamuna-chars","jamalpur-nakshi-kantha"]},"jashore":{"en":"Jashore","div":"khulna","tag":"Date palm gur, flower fields and a poet's river","lede":"Jashore is a market town of the south-west plains, famous for winter date palm molasses and for the flower fields of Gadkhali that supply much of the country. Michael Madhusudan Dutt's childhood home on the Kopotakkho draws literary visitors, and Jashore embroidery is known nationwide.","img":"e48b37d0","mx":1920,"glance":[],"known":["Khejur gur","Gadkhali flower fields","Michael Madhusudan Dutt","Jashore embroidery"],"trips":[],"stay":[["Budget hotel","৳500–1,500"],["Good hotel","৳1,500–3,800"],["Upscale / resort","No data"]],"peak":"","order":["sagardari-madhusudan-home","gadkhali-flower-fields","chanchra-shiva-temple","benapole-border","jashore-institute-library","jhanpa-baor","jashore-khejur-gur","jamtala-rosogolla","joljog-luchi-jashore","bharat-bhayna","jashore-embroidery","madhu-mela"]},"jhalokathi":{"en":"Jhalokathi","div":"barishal","tag":"Guava canals, shitalpati mats and river ghats","lede":"Jhalokathi's motto pairs guava and shitalpati, the cool woven mat. In the monsoon, the canals of Bhimruli fill with boats laden with guava, and the riverside town sits where the Sugandha and Bishkhali meet. Old zamindar ruins and weaving villages fill out a slow, water-bound district.","img":"0e65eb51","mx":1920,"glance":[],"known":["Bhimruli floating guava market","Shitalpati","Guava","Kirtipasha Zamindar Bari"],"trips":[],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["bhimruli-floating-market","kirtipasha-zamindar-bari","gabkhan-bridge","saturia-zamindar-bari","jhalokathi-guava","jhalokathi-amra","jhalokathi-rasgolla","sugandha-riverfront","khanbari-mosque-complex","chhoilar-char","jhalokathi-shitalpati"]},"jhenaidah":{"en":"Jhenaidah","div":"khulna","tag":"A giant banyan, old mosques and Gazi's legend","lede":"Jhenaidah is a farming district of bananas, betel leaf and date palms on the south-west plains. At Barobazar, excavated sultanate-era mosques recall an old trading town tied to the folk tale of Gazi, Kalu and Champaboti, and near Kaliganj a vast banyan spreads across acres of ground.","img":"cc7b768e","mx":1920,"glance":[],"known":["Mallikpur banyan tree","Barobazar mosques","Kaliganj langcha","Date palm gur"],"trips":[],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["mallikpur-banyan-tree","barobazar-mosques","shailkupa-shahi-mosque","naldanga-rajbari","kaliganj-langcha","jhenaidah-patali-gur","molla-hotel-beef-bhuna","dhol-samudra-dighi","miyar-dalan","gazi-kalu-champaboti"]},"joypurhat":{"en":"Joypurhat","div":"rajshahi","tag":"Sugarcane fields, old temples and quiet border villages","lede":"Joypurhat is a small, farming district on the edge of the Barind tract, known for its sugar mill, vegetables and village heritage. It is an easy base for nearby Paharpur, and rewards slow travellers with old temples, ponds and zamindar ruins.","img":"925574cd","mx":1920,"glance":[],"known":["Joypurhat Sugar Mill","Gopinathpur Temple","Lotiraj kochu","Lakma Rajbari"],"trips":[],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["gopinathpur-temple","nandail-dighi","joypurhat-sugar-mill","hinda-kasba-shahi-mosque","lotiraj-kochu","joypurhat-akher-gur","lakma-rajbari","gopinathpur-mela"]},"khagrachhari":{"en":"Khagrachhari","div":"chattogram","tag":"Caves, hill streams and the gateway to Sajek","lede":"Khagrachhari is a quieter corner of the Chittagong Hill Tracts, home to Chakma, Marma and Tripura communities. It has a pitch-dark cave you walk through by torchlight, waterfalls over sloping rock and a sacred lake on a hilltop. Most travellers pass through on the way to Sajek, but it rewards a day or two of its own.","img":"c785d656","mx":1920,"glance":[],"known":["Alutila cave","Richhang waterfall","Gateway to Sajek","Tripura culture","Hill malta"],"trips":["rangamati-khagrachhari-sajek"],"stay":[["Budget hotel","৳500–2,000"],["Good hotel","৳2,500–5,500"],["Upscale / resort","No data"]],"peak":"Peak season: Many Sajek travellers spend a night in Khagrachhari town, so rooms get scarce on long holidays.","order":["alutila-cave","richhang-waterfall","debota-pukur","khagrachhari-horticulture-park","ramgarh-lake","khagrachhari-malta","sidol-hill-cuisine","khagrachhari-hebang","khagrachhari-amrapali-mango","hazachora-waterfall","garia-dance","rignai-risa-weaving"]},"khulna":{"en":"Khulna","div":"khulna","tag":"Gateway city to the mangroves and the shrimp rivers","lede":"Khulna is the river port where most Sundarbans cruises begin, a working city of jute mills, prawn farms and busy ghats on the Rupsha. Beyond the city, lotus wetlands, a Tagore family home and stilt villages on the forest edge show a quieter side of the south-west.","img":"1821592e","mx":1920,"glance":[],"known":["Sundarbans boat trips","Chui jhal mutton","Golda chingri","Sundarbans honey","Rupsha river"],"trips":["sundarbans-and-bagerhat"],"stay":[["Budget hotel","৳1,000–2,500"],["Good hotel","৳2,100–3,500"],["Upscale / resort","৳5,750–16,500"]],"peak":"","order":["khulna-sundarbans-cruise","rupsha-riverfront","dakshindihi-rabindra-complex","bhutiar-padma-bil","khulna-divisional-museum","gollamari-memorial","chuknagar-chui-jhal","golda-chingri","sundarbans-honey","indromohon-sweets-khulna","rupsha-ghat-street-food","kalabogi-stilt-village","masjidkur-mosque","pc-roy-birthplace-raruli","moual-honey-hunters"]},"kishoreganj":{"en":"Kishoreganj","div":"dhaka","tag":"Haor roads, inland seas and the great Sholakia Eid","lede":"Eastern Kishoreganj is haor country: in the rains, huge wetlands swell into inland seas dotted with village islands. The district also holds the country's largest Eid congregation at Sholakia and the memory of the medieval poet Chandrabati.","img":"7ed9341d","mx":1920,"glance":[],"known":["Nikli and Mithamoin haors","Sholakia Eidgah","Pagla Mosque","Haor fish and duck"],"trips":[],"stay":[["Budget hotel","৳700–1,800"],["Good hotel","৳1,800–4,000"],["Upscale / resort","৳8,000–15,000"]],"peak":"","order":["nikli-haor","itna-mithamoin-austagram-road","pagla-mosque-kishoreganj","egarosindur-shah-mahmud-mosque","qutub-shah-mosque-austagram","shahidi-mosque-kishoreganj","kishoreganj-haor-fish","kishoreganj-haor-duck","austagram-paneer","jangalbari-fort","chandrabati-shiva-temple","guroi-shahi-mosque","sholakia-eid"]},"kurigram":{"en":"Kurigram","div":"rangpur","tag":"Where the Brahmaputra enters, with chars and Bhawaiya","lede":"Kurigram is the far northern corner where the Brahmaputra flows in from India, joined by the Teesta, Dharla and Dudhkumar. It is a land of shifting river islands (chars), country boats and Bhawaiya, the plaintive folk songs of the north.","img":"40134dc2","mx":1920,"glance":[],"known":["Brahmaputra and its chars","Chilmari river port","Bhawaiya songs","Dharla river","Sonahat"],"trips":[],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["dharla-riverfront","chilmari-river-port","sonahat-bridge","ulipur-munshibari","chandamari-mosque","kotheshwar-shiva-temple","kurigram-river-fish","char-bhutta","kurigram-charchom","ulipur-khirmohon","jhontu-mistanna-bhandar","bhawaiya-museum-ulipur","mekurtari-shahi-mosque","naodanga-zamindar-bari","kurigram-bhawaiya"]},"kushtia":{"en":"Kushtia","div":"khulna","tag":"Lalon's songs, Tagore's estate and the Padma","lede":"Kushtia is the cultural heart of the south-west. The mystic poet Lalon Shah lies buried at Cheuria, where Bauls gather to sing his songs, and Rabindranath Tagore wrote some of his finest work at Shilaidaha on the Padma. Add a sesame sweet, a historic railway bridge and Kumarkhali's looms.","img":"376d4b3b","mx":1920,"glance":[],"known":["Lalon Shah's akhra","Shilaidaha Kuthibari","Tiler khaja","Hardinge Bridge","Kumarkhali weaving"],"trips":["kushtia-lalon-and-tagore"],"stay":[["Budget hotel","৳500–2,000"],["Good hotel","৳2,000–3,500"],["Upscale / resort","No data"]],"peak":"Peak season: Rooms get scarce during the Lalon Mela (Oct and Mar) at Chheuria.","order":["lalon-akhra-cheuria","shilaidaha-kuthibari","bheramara-hardinge-bridge","tagore-lodge-kushtia","jhaudia-shahi-mosque","kangal-harinath-museum","swastipur-shahi-mosque","kushtia-tiler-khaja","kushtia-shon-papdi","kushtia-kulfi-malai","mir-mosharraf-hossain-home","jagati-railway-station","gorai-railway-bridge","lalon-smaran-utsab","kumarkhali-weaving"]},"lakshmipur":{"en":"Lakshmipur","div":"chattogram","tag":"Meghna shores, zamindar ruins and buffalo curd","lede":"Lakshmipur lies on the eastern bank of the lower Meghna, a land of betel-nut groves, coconut palms and soybean fields. The river beach at Ramgati draws crowds at sunset, and old zamindar houses and mosques hint at a wealthy past. No feast here is complete without a bowl of sour buffalo curd.","img":"83b59ac7","mx":1920,"glance":[],"known":["Ramgati buffalo curd","Alexander Meghna beach","Betel nut and coconut","Soybean fields","Dalal Bazar zamindar bari"],"trips":[],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["alexander-meghna-beach","dalal-bazar-zamindar-bari","raipur-jinn-mosque","majhu-chowdhury-hat","ramgati-mohisher-doi","lakshmipur-supari","lakshmipur-meghna-ilish","lakshmipur-coconut","khoa-sagar-dighi","lakshmipur-buffalo-curd-feast"]},"lalmonirhat":{"en":"Lalmonirhat","div":"rangpur","tag":"Former enclaves, the Tin Bigha corridor and Teesta chars","lede":"Lalmonirhat is a narrow border district stretching north along the Teesta, once full of enclaves (chhitmahal) that were exchanged with India in 2015. It is known for the Tin Bigha Corridor to Dahagram, the Burimari land port and quiet zamindar ruins.","img":"9d61abda","mx":1920,"glance":[],"known":["Tin Bigha Corridor","Dahagram–Angarpota","Burimari land port","Teesta river","Railway heritage"],"trips":[],"stay":[["Budget hotel","৳600–1,200"],["Good hotel","৳1,200–2,500"],["Upscale / resort","No data"]],"peak":"","order":["tin-bigha-corridor","burimari-land-port","kakina-zamindar-bari","harano-masjid-ramdas","teesta-rail-and-road-bridges","sindurmati-dighi","lalmonirhat-pelka","kaun-payesh","lalmonirhat-pradip-sweets","tushbhandar-zamindar-bari","noudabas-sal-forest","lalmonirhat-railway-heritage"]},"madaripur":{"en":"Madaripur","div":"dhaka","tag":"Date-palm gur, khirpuri and the Arial Khan river","lede":"Madaripur is a river district on the Arial Khan and the Padma, a land of date palms, wetlands and old Hindu landlord estates. It is known across Bangladesh for its winter khejur gur and its milky khirpuri sweet.","img":"4f4db14a","mx":1920,"glance":[],"known":["Khejur gur","Khirpuri","Shakuni Lake","Padma at Shibchar"],"trips":[],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["shakuni-lake","khalia-rajaram-mandir","shibchar-padma-riverside","madaripur-museum","pranab-math-bajitpur","madaripur-khirpuri","madaripur-khejur-gur","madaripur-ilish-bhaja","aowliapur-neelkuthi","charmuguria-eco-park","madaripur-gachhi-tradition"]},"magura":{"en":"Magura","div":"khulna","tag":"Raja Sitaram's capital on the Madhumati","lede":"Magura is a quiet river district between the Nabaganga, Garai and Madhumati. Its main draw is Mohammadpur, the 17th–18th century capital of the rebel Raja Sitaram Ray, where temples, tanks and palace ruins remain among villages. It is also the birthplace of poet Farrukh Ahmad.","img":"f9d9e8f2","mx":1920,"glance":[],"known":["Raja Sitaram Ray","Madhumati river","Poet Farrukh Ahmad","Date palm gur"],"trips":[],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["sitaram-rajbari-mohammadpur","kanainagar-temple","farrukh-ahmad-birthplace","sreepur-zamindar-bari","siddheshwari-math-magura","magura-khejur-gur","magura-winter-pitha","madhumati-mohammadpur-ghat","chhandra-zamindar-bari","gachhi-date-palm-tapping"]},"manikganj":{"en":"Manikganj","div":"dhaka","tag":"Zamindar palaces on the Jamuna and Padma","lede":"Manikganj lies where the Jamuna meets the Padma, a flat, fertile district of mustard fields and river ghats. Its zamindars left behind some of the grandest country palaces near Dhaka, and its winter date-palm molasses is famous across Bangladesh.","img":"9788e9ca","mx":1920,"glance":[],"known":["Baliati Zamindar Bari","Teota Zamindar Bari","Hazari gur","Padma–Jamuna confluence"],"trips":[],"stay":[["Budget hotel","৳1,000–2,500"],["Good hotel","৳2,500–10,000"],["Upscale / resort","৳10,000–20,000"]],"peak":"Peak season: Resorts charge more on Friday–Saturday and public holidays.","order":["baliati-zamindar-bari","teota-zamindar-bari","aricha-jamuna-riverside","machain-shahi-mosque","betila-zamindar-bari","manikganj-hazari-gur","manikganj-river-fish","ghior-nizam-mishti","manikganj-mustard-fields","dhankora-zamindar-bari","manikganj-date-palm-tapping"]},"meherpur":{"en":"Meherpur","div":"khulna","tag":"Where the 1971 government was sworn in under mango trees","lede":"Meherpur is a small border district with an outsized place in history: on 17 April 1971 the first government of Bangladesh took oath in a mango grove at Baidyanathtala, renamed Mujibnagar. Indigo-era mansions and two century-old sweets complete the picture.","img":"68d2e5b9","mx":1920,"glance":[],"known":["Mujibnagar Memorial","Amjhupi Nilkuthi","Sabitri sweet","Rosokodom sweet"],"trips":[],"stay":[["Budget hotel","৳500–1,500"],["Good hotel","৳1,500–2,500"],["Upscale / resort","No data"]],"peak":"","order":["mujibnagar-memorial","amjhupi-nilkuthi","bhatpara-nilkuthi","meherpur-sabitri","meherpur-rosokodom","meherpur-himsagar-mango","ballavpur-mission","nigamananda-ashram-kutubpur","anandabas-ten-dome-mosque","mujibnagar-day"]},"moulvibazar":{"en":"Moulvibazar","div":"sylhet","tag":"Tea country, rainforest and Manipuri dance","lede":"Moulvibazar is the heart of Bangladesh's tea country, with Srimangal surrounded by endless green estates. Between the gardens lie patches of tropical forest full of gibbons, a great wetland that fills with winter birds, and one of the country's best-known waterfalls. Manipuri, Khasi and tea-worker communities give the district a rich cultural mix.","img":"a4c8c049","mx":1920,"glance":[],"known":["Srimangal tea gardens","Lawachara forest","Madhabkunda waterfall","Seven-layer tea","Manipuri dance"],"trips":["sylhet-tea-and-rivers"],"stay":[["Budget hotel","৳1,000–2,000"],["Good hotel","৳2,000–5,500"],["Upscale / resort","৳8,000–35,000"]],"peak":"Peak season: Resorts fill up on weekends and in winter; most quoted rates add 15% VAT and sometimes a service charge.","order":["srimangal-tea-gardens","lawachara-national-park","madhabkunda-waterfall","hakaluki-haor","baikka-beel","madhabpur-lake","srimangal-tea-museum","seven-layer-tea","srimangal-pineapple","moulvibazar-chunga-pitha","srimangal-lemon","hail-haor-fish","hamham-waterfall","adampur-forest","barshijora-eco-park","goyghor-khojar-mosque","manipuri-dance"]},"munshiganj":{"en":"Munshiganj","div":"dhaka","tag":"Ancient Bikrampur, Padma hilsa and Bhagyakul sweets","lede":"Munshiganj is the old land of Bikrampur, birthplace of the Buddhist scholar Atish Dipankar and seat of medieval Bengali kings. Today it is known for the Padma Bridge, fried hilsa at Mawa, Mughal forts and endless potato fields.","img":"2fc7abce","mx":1920,"glance":[],"known":["Bikrampur heritage","Idrakpur Fort","Mawa hilsa","Bhagyakul sweets"],"trips":[],"stay":[["Budget hotel","৳1,000–2,500"],["Good hotel","৳2,500–10,000"],["Upscale / resort","৳10,000–20,000"]],"peak":"Peak season: Resorts charge more on Friday–Saturday and public holidays.","order":["idrakpur-fort","mawa-padma-riverside","sonarang-twin-temples","baba-adam-mosque","jc-bose-complex-rarikhal","mawa-ilish-bhaja","bhagyakul-mishti","munshiganj-patkhir","louhajang-rosogolla","nateshwar-buddhist-site","arial-beel","bikrampur-atish-dipankar"]},"mymensingh":{"en":"Mymensingh","div":"mymensingh","tag":"Brahmaputra banks, zamindar palaces and Muktagacha monda","lede":"Mymensingh is an old university and riverside town on the Old Brahmaputra, the heartland of Bengal's folk ballads. Its zamindar palaces, the Zainul Abedin museum and the famous monda of Muktagacha make it an easy and rewarding stop north of Dhaka.","img":"8011c0b0","mx":1920,"glance":[],"known":["Muktagacha monda","Shashi Lodge","Old Brahmaputra riverside","Mymensingh Gitika ballads"],"trips":["birishiri-and-mymensingh"],"stay":[["Budget hotel","৳800–2,000"],["Good hotel","৳2,000–5,000"],["Upscale / resort","No data"]],"peak":"","order":["shashi-lodge","zainul-abedin-museum-riverside","muktagacha-rajbari","bau-botanical-garden","nazrul-smriti-kendra-trishal","muktagacha-monda","mymensingh-river-fish","mymensingh-malaikari","fulbaria-lal-chini","nandail-chyapa-shutki","alexander-castle-mymensingh","kadigarh-national-park","atharobari-zamindar-bari","mymensingh-gitika"]},"naogaon":{"en":"Naogaon","div":"rajshahi","tag":"Buddhist monasteries, Barind rice and Tagore's estate","lede":"Naogaon is home to Paharpur, the ruins of Somapura Mahavihara and a UNESCO World Heritage Site, along with other traces of the Pala-era Buddhist world. Its red Barind soil grows rice and, increasingly, mangoes, and Tagore once managed his family estate here at Patisar.","img":"5f8d7150","mx":1920,"glance":[],"known":["Paharpur Buddhist Vihara","Kusumba Mosque","Pera sandesh","Mango orchards","Patisar"],"trips":["north-bengal-heritage-by-bike"],"stay":[["Budget hotel","৳500–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["somapura-mahavihara","kusumba-mosque","patisar-kuthibari","dibar-dighi","alta-dighi-national-park","dubalhati-rajbari","raktadaha-beel","naogaon-pera-sandesh","naogaon-mango","naogaon-sabbir-biryani","jagaddala-mahavihara","halud-vihara","bhimer-panti","patisar-rabindra-jayanti"]},"narail":{"en":"Narail","div":"khulna","tag":"S.M. Sultan's river town on the Chitra","lede":"Narail is a small, green town on the Chitra river, the lifelong home of painter S.M. Sultan, whose muscular peasants changed Bangladeshi art. Boat races on the Chitra, a decaying zamindar house and winter date palm sweets give the district its character.","img":"3266cd65","mx":1920,"glance":[],"known":["S.M. Sultan","Chitra river boat races","Narail Zamindar Bari","Patali gur"],"trips":[],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["sm-sultan-memorial","narail-zamindar-bari","chitra-riverfront-narail","hatbaria-zamindar-bari","raigram-jor-bangla-temple","narail-nalini-patali","narail-khejur-rosh","nihar-ranjan-gupta-house","goal-bathan-mosque","chitra-boat-race-sultan-mela"]},"narayanganj":{"en":"Narayanganj","div":"dhaka","tag":"Old Bengal's capital and the looms of Jamdani","lede":"Narayanganj is a river-port city on the Shitalakshya, but just beyond it lies Sonargaon, once a capital of independent Bengal. Abandoned merchant houses at Panam Nagar, Mughal river forts and the Jamdani weaving villages make it a rewarding day trip from Dhaka.","img":"74ac3329","mx":1920,"glance":[],"known":["Panam Nagar","Sonargaon","Jamdani weaving","Mughal river forts"],"trips":["dhaka-old-town-and-sonargaon"],"stay":[["Budget hotel","৳1,000–2,500"],["Good hotel","৳2,500–10,000"],["Upscale / resort","৳10,000–20,000"]],"peak":"Peak season: Resorts charge more on Friday–Saturday and public holidays.","order":["panam-nagar","sonargaon-folk-art-museum","hajiganj-fort","sonakanda-fort","langalbandh","kadam-rasul-dargah","lokenath-ashram-barodi","narayanganj-sweet-curd","goaldi-mosque","fath-shah-mosque-mograpara","jamdani-weaving","langalbandh-ashtami-snan"]},"narsingdi":{"en":"Narsingdi","div":"dhaka","tag":"An ancient city on the Old Brahmaputra and busy looms","lede":"Narsingdi sits between the Meghna and the Old Brahmaputra, a district of weavers, banana groves and lotkon orchards. Its great surprise is Wari-Bateshwar, the excavated remains of a fortified trading town around 2,500 years old.","img":"c3d6dd50","mx":1920,"glance":[],"known":["Wari-Bateshwar ruins","Handloom and textile markets","Sagar bananas","Lotkon fruit"],"trips":[],"stay":[["Budget hotel","৳1,000–2,500"],["Good hotel","৳2,500–10,000"],["Upscale / resort","৳10,000–20,000"]],"peak":"Peak season: Resorts charge more on Friday–Saturday and public holidays.","order":["wari-bateshwar","baburhat-cloth-market","narsingdi-meghna-riverside","dream-holiday-park","bir-sreshtho-matiur-rahman-museum","narsingdi-lotkon","narsingdi-sagar-kola","narsingdi-nakshi-pitha","shibpur-lotkon-orchards","narsingdi-handloom"]},"natore":{"en":"Natore","div":"rajshahi","tag":"Royal palaces, kacha golla and the great Chalan Beel","lede":"Natore is a small, leafy town shaped by its zamindar past, with Rani Bhabani's palace and the elegant Dighapatia palace now known as Uttara Gonobhaban. East of town stretches Chalan Beel, the country's largest wetland, and Natore's soft kacha golla is famous nationwide.","img":"167c7f6e","mx":1920,"glance":[],"known":["Kacha golla","Uttara Gonobhaban","Rani Bhabani's palace","Chalan Beel","Banalata Sen"],"trips":["north-bengal-heritage-by-bike"],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["uttara-gonobhaban","natore-rajbari","chalan-beel","shahid-sagar-natore","bonpara-lourdes-church","natore-kacha-golla","chalan-beel-fish","lalpur-khejur-gur","halti-beel","chalan-beel-museum","laxmipur-aushodhi-gram"]},"netrokona":{"en":"Netrokona","div":"mymensingh","tag":"China-clay hills, the Someshwari and the haors","lede":"Netrokona runs from the Garo Hills on the Indian border down to the great haor wetlands. In the north, Birisiri and Durgapur offer clear rivers, white china-clay hills and Garo and Hajong culture; in the south, the haors turn into inland seas each monsoon.","img":"04c587f8","mx":1920,"glance":[],"known":["Birisiri and the Someshwari river","China-clay hills of Bijoypur","Balish misti","Baul songs"],"trips":["birishiri-and-mymensingh"],"stay":[["Budget hotel","৳1,000–2,000"],["Good hotel","৳2,500–4,000"],["Upscale / resort","No data"]],"peak":"","order":["birisiri-someshwari","bijoypur-china-clay-hills","dingapota-haor","chandradinga-hill","uchitpur-haor","netrokona-balish-misti","netrokona-haor-fish","ranikhong-mission","saat-shahid-mazar-lengura","roailbari-fort","netrokona-baul-songs","birisiri-wangala"]},"nilphamari":{"en":"Nilphamari","div":"rangpur","tag":"Indigo history, the Teesta Barrage and a railway town","lede":"Nilphamari takes its name from the indigo (nil) plantations of the colonial era. Today it is known for the Teesta Barrage at Dalia, the great pond of Nilsagar and the railway town of Saidpur, with its glittering Chini Mosque and distinctive food culture.","img":"7bd52d06","mx":1920,"glance":[],"known":["Teesta Barrage","Nilsagar","Chini Mosque","Saidpur railway workshop","Indigo history"],"trips":[],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["teesta-barrage","nilsagar","chini-mosque-saidpur","saidpur-street-food","nilphamari-char-peanuts","dharmapal-garh","harishchandra-path","saidpur-railway-heritage"]},"noakhali":{"en":"Noakhali","div":"chattogram","tag":"Deer islands, coastal chars and Gandhi's peace walk","lede":"Noakhali reaches from farmland in the north to new islands rising from the Meghna estuary in the south. Its far end, Nijhum Dwip, is a mangrove island where spotted deer graze at dusk. Inland, the district holds memories of Gandhi's 1946–47 peace mission and fine Mughal-era mosques.","img":"c1d4d402","mx":1920,"glance":[],"known":["Nijhum Dwip","Spotted deer","Gandhi Ashram","Buffalo curd","Hatiya island"],"trips":[],"stay":[["Budget hotel","৳1,000–2,000"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"Peak season: Nijhum Dwip has few rooms; book ahead for winter weekends.","order":["nijhum-dwip","hatiya-island","gandhi-ashram-joyag","bajra-shahi-mosque","noakhali-char-mohisher-doi","noakhali-chitoi-pitha-duck","hatiya-ilish-nona-ilish","musapur-closure","ramzan-mia-mosque","noakhali-buffalo-bathan"]},"pabna":{"en":"Pabna","div":"rajshahi","tag":"Padma bridges, litchi groves and old riverside temples","lede":"Pabna lies on the north bank of the Padma, where the century-old Hardinge Bridge and the newer Lalon Shah Bridge cross to Kushtia. The town has graceful temples and the childhood home of actress Suchitra Sen, while Ishwardi's orchards are known for litchis.","img":"c953a144","mx":1920,"glance":[],"known":["Hardinge Bridge","Ishwardi litchi","Jor Bangla Temple","Suchitra Sen's house","Handloom and hosiery"],"trips":[],"stay":[["Budget hotel","৳800–2,000"],["Good hotel","৳2,000–4,000"],["Upscale / resort","No data"]],"peak":"","order":["hardinge-bridge","jor-bangla-temple-pabna","suchitra-sen-house","taras-bhaban-pabna","shitlai-rajbari","ishwardi-litchi","pabna-ghee","ishwardi-kori-pal-doi","chatmohar-shahi-mosque","handial-jagannath-temple","gajnar-beel","pabna-handloom-hosiery"]},"panchagarh":{"en":"Panchagarh","div":"rangpur","tag":"Tea on the plains and Kanchenjunga on the horizon","lede":"Panchagarh is Bangladesh's northernmost district, where flatland tea gardens stretch to the Indian border and, on clear autumn and winter mornings, the snowy Kanchenjunga range appears from Tetulia. Its rivers carry stones down from the hills, and its ancient fort city of Bhitargarh hints at a long history.","img":"903840d2","mx":1920,"glance":[],"known":["Kanchenjunga view from Tetulia","Flatland tea gardens","Banglabandha Zero Point","Rocks Museum","Mahananda river"],"trips":[],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"Peak season: In the Kanchenjunga-viewing season (October–November) Tetulia's few rooms fill fast; book the dak bungalow through the Zila Parishad in advance.","order":["tetulia-kanchenjunga-view","tetulia-tea-gardens","banglabandha-zero-point","panchagarh-rocks-museum","mirzapur-shahi-mosque","maharajar-dighi","panchagarh-tea","panchagarh-malta-orange","bhitargarh","golokdham-temple","mahananda-stone-collectors"]},"patuakhali":{"en":"Patuakhali","div":"barishal","tag":"Kuakata, where the sea shows both sunrise and sunset","lede":"Patuakhali runs down to the Bay of Bengal at Kuakata, a long beach where you can watch the sun both rise and set over the sea. Rakhine communities, Buddhist temples, coastal forests and fishing camps give the coast a character all its own.","img":"49d9bfc0","mx":1920,"glance":[],"known":["Kuakata sea beach","Sunrise and sunset over the sea","Rakhine culture","Fresh seafood"],"trips":["kuakata-sunrise-sunset"],"stay":[["Budget hotel","৳1,000–3,000"],["Good hotel","৳2,500–6,500"],["Upscale / resort","৳9,000–30,000"]],"peak":"Peak season: About 150 hotels; on Eid and long holidays rooms run out and some visitors end up sleeping on the beach. Off-season and festival discounts of up to 50% are common.","order":["kuakata-sea-beach","gangamati-forest","kuakata-buddhist-temples","majidbaria-shahi-mosque","kuakata-seafood-fry","kuakata-shutki","patuakhali-watermelon","sonar-char","kuakata-water-museum","jahajmara-beach","kuakata-rash-mela","rakhine-weaving"]},"pirojpur":{"en":"Pirojpur","div":"barishal","tag":"Floating guava markets and amra orchards","lede":"Pirojpur is a land of canals, orchards and boats. In the monsoon, farmers in Swarupkathi bring guavas to floating markets at Atghar-Kuriana, and boat markets sell the wooden canoes everyone needs. Amra, guava and timber nurseries define the green, watery landscape.","img":"f8c915bb","mx":1920,"glance":[],"known":["Atghar-Kuriana floating market","Amra","Swarupkathi guava","Boat markets"],"trips":[],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["atghar-kuriana-floating-market","rayerkathi-zamindar-bari","baleshwar-riverfront","momin-mosque","pirojpur-amra","swarupkathi-guava","nazirpur-floating-garden-vegetables","swarupkathi-nurseries","nazirpur-floating-gardens","atghar-boat-market"]},"rajbari":{"en":"Rajbari","div":"dhaka","tag":"Ferry ghats, Padma views and khir chomchom","lede":"Rajbari sits on the south bank of the Padma, where the great river is joined by the Jamuna. Its Goalanda and Daulatdia ghats have been gateways between Dhaka and the south-west for over a century, and the district keeps a sweet tooth and a literary heritage.","img":"88e78072","mx":1920,"glance":[],"known":["Daulatdia–Goalanda ghat","Godar Bazar riverside","Khir chomchom","Mir Mosharraf Hossain"],"trips":[],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["godar-bazar-padma","daulatdia-ghat","padamdi-mir-mosharraf","rajbari-khir-chomchom","goalanda-ghat-curry","rajbari-jamun","kalyan-dighi-baliakandi","rajbari-bishad-sindhu-heritage"]},"rajshahi":{"en":"Rajshahi","div":"rajshahi","tag":"Mango orchards, silk looms and terracotta temples","lede":"Rajshahi is a calm, green city on the north bank of the Padma, known for its mango orchards, silk weaving and one of the country's oldest museums. A short ride east, the village of Puthia holds a remarkable cluster of terracotta-decorated Hindu temples.","img":"6066c2cd","mx":1920,"glance":[],"known":["Mangoes","Rajshahi silk","Puthia temples","Varendra Research Museum","Padma riverfront"],"trips":["north-bengal-heritage-by-bike"],"stay":[["Budget hotel","৳1,500–3,000"],["Good hotel","৳3,500–5,000"],["Upscale / resort","৳6,500–10,500"]],"peak":"","order":["puthia-temple-complex","varendra-research-museum","rajshahi-padma-riverfront","boro-kuthi-rajshahi","shah-makhdum-dargah","rajshahi-central-park-zoo","rajshahi-university-campus","rajshahi-mango","rajshahi-khejur-gur","rajshahi-kala-bhuna","hoba-ghosh-rosogolla","rajshahi-roshkodom","bagha-mosque","kismat-maria-mosque","kheturi-dham","rajshahi-silk"]},"rangamati":{"en":"Rangamati","div":"chattogram","tag":"A lake of hills, boats and cloud-top villages","lede":"Rangamati is built around Kaptai Lake, a huge reservoir whose flooded valleys turned hilltops into islands. Boats are the main way to get around, past Chakma villages, Buddhist temples and waterfalls. To the north, the Sajek Valley sits high on a ridge above the clouds.","img":"56f84af1","mx":1920,"glance":[],"known":["Kaptai Lake","Hanging bridge","Sajek Valley","Chakma culture","Biju festival"],"trips":["rangamati-khagrachhari-sajek"],"stay":[["Budget hotel","৳800–2,000"],["Good hotel","৳2,000–3,600"],["Upscale / resort","৳5,000–15,000"]],"peak":"Peak season: Sajek has about 100–135 resorts and cottages; on long holidays (Eid, December) every room is booked in advance, so book before you go.","order":["kaptai-lake","rangamati-hanging-bridge","sajek-valley","shuvolong-waterfall","rajban-vihara","kaptai-national-park","rangamati-tribal-cultural-museum","pajon","sajek-bamboo-chicken","kaptai-lake-kachki-chapila","naniarchar-pineapple","rangamati-hill-orange","konglak-para","dhuppani-waterfall","furomon-hill","biju-boisabi-festival","kathin-chibar-dan"]},"rangpur":{"en":"Rangpur","div":"rangpur","tag":"A royal palace, Rokeya's village and woven shotoronji","lede":"Rangpur is the main city of the far north, known for the white Tajhat Palace, the handwoven shotoronji rugs of Nisbetganj and the Haribhanga mango. South of the city, Pairaband was the birthplace of Begum Rokeya, pioneer of women's education in Bengal.","img":"0f939ff4","mx":1920,"glance":[],"known":["Tajhat Palace","Shotoronji weaving","Haribhanga mango","Begum Rokeya","Bhawaiya songs"],"trips":[],"stay":[["Budget hotel","৳800–2,000"],["Good hotel","৳4,500–7,000"],["Upscale / resort","No data"]],"peak":"","order":["tajhat-palace","carmichael-college","begum-rokeya-memorial","bhinno-jagat-park","chikli-beel-park","rangpur-zoo","haribhanga-mango","rangpur-shidol","rangpur-shingara-house","rangpur-sholka","mithapukur-mosque","itakumari-zamindar-bari","laldighi-nine-dome-mosque","nisbetganj-shotoronji"]},"satkhira":{"en":"Satkhira","div":"khulna","tag":"Early mangoes and the western edge of the Sundarbans","lede":"Satkhira sits in the far south-west, bordering India and the western Sundarbans. Its orchards ripen some of the country's earliest mangoes, its coastal ghers raise crab and shrimp, and Shyamnagar's Munshiganj and Burigoalini lead straight into the forest.","img":"459415f3","mx":1920,"glance":[],"known":["Satkhira mangoes","Western Sundarbans","Jeshoreshwari Kali temple","Crab and shrimp farming"],"trips":[],"stay":[["Budget hotel","৳800–2,000"],["Good hotel","৳2,000–4,000"],["Upscale / resort","No data"]],"peak":"","order":["munshiganj-burigoalini","kalagachhia-eco-tourism","jeshoreshwari-kali-temple","mandarbaria-beach","prabajpur-shahi-mosque","satkhira-mango","satkhira-crab","satkhira-sandesh","ishwaripur-hammamkhana","tetulia-jami-mosque","nakipur-zamindar-bari","bonbibi-puja"]},"shariatpur":{"en":"Shariatpur","div":"dhaka","tag":"Where the Padma Bridge lands and the Meghna meets","lede":"Shariatpur is a low, river-bound district between the Padma and the Meghna, named after the reformer Haji Shariatullah. The Padma Bridge now lands at Jajira, opening up old temples, shrines and riverside villages to easy day trips from Dhaka.","img":"311cd955","mx":1920,"glance":[],"known":["Padma Bridge at Jajira","Dhanuka Manasa Bari","Hilsa","Palong bazar rasgolla"],"trips":[],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["jajira-padma-bridge-view","dhanuka-manasa-bari","sureshwar-darbar-sharif","burirhat-mosque","palong-bazar-rasgolla","shariatpur-bibikhana-pitha","shariatpur-hilsa","rudrakar-math","kartikpur-zamindar-bari","monohar-bazar-hilsa-fair"]},"sherpur":{"en":"Sherpur","div":"mymensingh","tag":"Garo Hills foothills, Gajni and fragrant Tulshimala rice","lede":"Sherpur sits at the foot of the Garo Hills, with sal-covered ridges, streams and indigenous villages along its northern border. Gajni and Madhutila draw weekend crowds, while the district's aromatic Tulshimala rice and chhanar payesh are known well beyond it.","img":"a5365720","mx":1920,"glance":[],"known":["Gajni recreation centre","Madhutila Eco Park","Tulshimala rice","Chhanar payesh"],"trips":[],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["gajni-abokash-kendro","madhutila-eco-park","rajar-pahar","mai-saheba-mosque","sherpur-chhanar-payesh","sherpur-tulshimala-rice","sherpur-dailer-amitti","panihata-tarani-pahar","ghagra-khan-bari-mosque","sherpur-indigenous-cultures"]},"sirajganj":{"en":"Sirajganj","div":"rajshahi","tag":"Jamuna riverbanks, Tagore's estate and busy handlooms","lede":"Sirajganj stands on the west bank of the mighty Jamuna, crossed here by the Jamuna Bridge. Its villages are among the country's great weaving centres, Tagore once managed his estate from Shahzadpur, and its dairy belt makes the region's famous ghee and sweets.","img":"d0e4bfc0","mx":1920,"glance":[],"known":["Jamuna Bridge","Handloom weaving","Shahzadpur Kachharibari","Enayetpur pantua","Dairy and ghee"],"trips":[],"stay":[["Budget hotel","৳800–2,000"],["Good hotel","৳2,000–4,000"],["Upscale / resort","No data"]],"peak":"","order":["jamuna-bridge","sirajganj-hard-point","shahzadpur-kachharibari","elliott-bridge-sirajganj","shahzadpur-dargah-mosque","jamuna-bridge-west-eco-park","enayetpur-pantua","sirajganj-dairy-ghee","mohishluti-chalan-beel-shutki","hatikumrul-navaratna-temple","potajia-navaratna-temple","sirajganj-handloom"]},"sunamganj":{"en":"Sunamganj","div":"sylhet","tag":"Haor waters, border hills and mystic songs","lede":"Sunamganj is a land of haors, huge seasonal wetlands that turn into inland seas in the rainy months, with the Meghalaya hills rising sharply along its northern edge. Tanguar Haor stretches to the hills, rivers run clear over stones near the border, and the songs of Hason Raja and Shah Abdul Karim are still sung in every village.","img":"fa931008","mx":1920,"glance":[],"known":["Tanguar Haor","Niladri Lake","Barikka Tila and Jadukata river","Hason Raja","Shah Abdul Karim"],"trips":["haor-and-hills-sunamganj"],"stay":[["Budget hotel","৳200–1,000"],["Good hotel","৳1,500–2,500"],["Upscale / resort","৳10,000–12,000"]],"peak":"Peak season: Houseboats run mainly in the monsoon (June–September); weekends and full-moon nights cost more.","order":["tanguar-haor","niladri-lake","barikka-tila-jadukata","shimul-bagan-tahirpur","pagla-jame-mosque","hason-raja-museum-sunamganj","sunamganj-haor-duck","sunamganj-haor-fish","lakmachhara","hason-raja-songs","shah-abdul-karim-baul"]},"sylhet":{"en":"Sylhet","div":"sylhet","tag":"Tea hills, swamp forests and stone rivers","lede":"Sylhet lies at the foot of the Meghalaya hills, where clear rivers run out of India over beds of stone. Within reach of the city are a flooded swamp forest, emerald rivers and rolling tea gardens. The city itself is a place of pilgrimage, centred on the shrine of the saint Shah Jalal.","img":"5d1d11c1","mx":1920,"glance":[],"known":["Ratargul swamp forest","Jaflong","Tea gardens","Shah Jalal shrine","Shatkora beef"],"trips":["sylhet-tea-and-rivers"],"stay":[["Budget hotel","৳1,000–2,500"],["Good hotel","৳2,800–6,000"],["Upscale / resort","৳8,000–20,000"]],"peak":"Peak season: Winter, the monsoon (for waterfalls and haors) and Eid/Puja holidays fill most hotels; big hotels gave up to 50% off in Ramadan.","order":["ratargul-swamp-forest","jaflong","bichanakandi","lalakhal","shah-jalal-dargah","malnicherra-tea-estate","bholaganj-sada-pathor","shah-paran-shrine","keane-bridge","shatkora-beef","sylheti-akhni","sylheti-hidol-bhorta","sylheti-bhorta-bhaat-meal","sylhet-jara-shashni-citrus","panthumai-waterfall","dibir-haor","khadimnagar-national-park","sylhet-shital-pati"]},"tangail":{"en":"Tangail","div":"dhaka","tag":"Saree looms, Porabari chomchom and Madhupur's sal forest","lede":"Tangail is famous across Bangladesh for two things: its handwoven saris and its chomchom. Beyond these, it has the Madhupur sal forest with Garo villages, ornate zamindar houses and the Jamuna on its western edge.","img":"0c6bf90f","mx":1920,"glance":[],"known":["Tangail saree","Porabari chomchom","Madhupur forest","Mohera Zamindar Bari"],"trips":[],"stay":[["Budget hotel","৳800–2,000"],["Good hotel","৳2,000–4,000"],["Upscale / resort","No data"]],"peak":"","order":["mohera-zamindar-bari","atia-mosque","madhupur-forest","201-dome-mosque","dhanbari-nawab-palace","karatia-zamindar-bari","porabari-chomchom","madhupur-pineapple","jamurki-sandesh","nagarpur-zamindar-bari","pakutia-zamindar-bari","hemnagar-zamindar-bari","tangail-saree-weaving","madhupur-garo-culture"]},"thakurgaon":{"en":"Thakurgaon","div":"rangpur","tag":"Giant mango trees, quiet dighis and old village fairs","lede":"Thakurgaon is a peaceful farming district in the far north-west, with wide fields, Santal villages and large old ponds. It is known for a vast, sprawling mango tree in Baliadangi, the 'jinn mosque' at Balia and the centuries-old Nekmarad fair.","img":"e647b04b","mx":1920,"glance":[],"known":["Baliadangi's giant mango tree","Balia Mosque","Ramrai Dighi","Nekmarad Mela","Surjapuri mango"],"trips":[],"stay":[["Budget hotel","৳600–1,500"],["Good hotel","৳1,500–3,000"],["Upscale / resort","No data"]],"peak":"","order":["balia-mosque","ramrai-dighi","haripur-rajbari","jamalpur-zamindar-bari-mosque","raja-tonkonath-palace","surjapuri-mango","thakurgaon-winter-pitha","baliadangi-giant-mango-tree","dholarhat-temple","khunia-dighi-memorial","lokayan-museum-akcha","nekmarad-mela"]}};
window.EB_DIVS=[{"id":"dhaka","bn":"Dhaka Division","en":"Dhaka","d":["dhaka","gazipur","narayanganj","narsingdi","manikganj","munshiganj","tangail","kishoreganj","faridpur","gopalganj","madaripur","rajbari","shariatpur"]},{"id":"chattogram","bn":"Chattogram Division","en":"Chattogram","d":["chattogram","coxs-bazar","bandarban","rangamati","khagrachhari","cumilla","brahmanbaria","chandpur","feni","noakhali","lakshmipur"]},{"id":"rajshahi","bn":"Rajshahi Division","en":"Rajshahi","d":["rajshahi","bogura","chapainawabganj","joypurhat","naogaon","natore","pabna","sirajganj"]},{"id":"khulna","bn":"Khulna Division","en":"Khulna","d":["khulna","bagerhat","satkhira","jashore","jhenaidah","magura","narail","kushtia","chuadanga","meherpur"]},{"id":"barishal","bn":"Barishal Division","en":"Barishal","d":["barishal","bhola","patuakhali","barguna","pirojpur","jhalokathi"]},{"id":"sylhet","bn":"Sylhet Division","en":"Sylhet","d":["sylhet","moulvibazar","habiganj","sunamganj"]},{"id":"rangpur","bn":"Rangpur Division","en":"Rangpur","d":["rangpur","dinajpur","thakurgaon","panchagarh","nilphamari","lalmonirhat","kurigram","gaibandha"]},{"id":"mymensingh","bn":"Mymensingh Division","en":"Mymensingh","d":["mymensingh","jamalpur","netrokona","sherpur"]}];
window.EB_TRIPS=[{"id":"coxs-bazar-and-bandarban","t":"Cox's Bazar & Bandarban","s":"beach and hills","lede":"Sunset on the world's longest natural beach, the marine drive to Himchari and Inani, then up into the clouds at Nilgiri and Nilachal and the golden temple above Bandarban town.","img":"6408af3e","mx":1920,"days":5,"km":910,"mode":"By bus","cost":8803,"season":"Winter, Late autumn","stops":["coxs-bazar-beach","himchari","inani-beach","nilachal-bandarban","nilgiri-bandarban","bandarban-golden-temple"]},{"id":"rangamati-khagrachhari-sajek","t":"Sajek & Rangamati","s":"clouds and Kaptai Lake","lede":"Wake above the clouds in Sajek Valley, explore Alutila cave and Richhang falls, then take a boat across Kaptai Lake to Shuvolong and the hanging bridge.","img":"72041c57","mx":1920,"days":5,"km":745,"mode":"By bus","cost":7723,"season":"Autumn, Late autumn, Winter","stops":["alutila-cave","richhang-waterfall","sajek-valley","kaptai-lake","shuvolong-waterfall","rangamati-hanging-bridge"]},{"id":"sundarbans-and-bagerhat","t":"Sundarbans & Bagerhat","s":"mangroves and Sixty Dome","lede":"The Sixty Dome Mosque and Khan Jahan Ali's tomb, a walk into the mangroves at Karamjal, and the river life of Khulna. Add a guided cruise for the deep forest.","img":"a943eed4","mx":1920,"days":4,"km":498,"mode":"By bus","cost":5191,"season":"Winter, Late autumn","stops":["sixty-dome-mosque","khan-jahan-ali-tomb","chunakhola-mosque","karamjal","rupsha-riverfront"]},{"id":"kuakata-sunrise-sunset","t":"Kuakata","s":"sunrise and sunset from one beach","lede":"Over the Padma bridge to the southern tip, where you can watch the sun rise and set over the sea. Rakhine temples, Gangamati forest and fresh fish by the shore.","img":"3460505a","mx":1920,"days":4,"km":635,"mode":"By bus","cost":6592,"season":"Winter, Late autumn, Spring","stops":["kuakata-sea-beach","gangamati-forest","kuakata-buddhist-temples"]},{"id":"dhaka-old-town-and-sonargaon","t":"Old Dhaka & Sonargaon","s":"Lalbagh to Panam Nagar","lede":"Lalbagh Fort, the pink Ahsan Manzil and the river at Sadarghat, then the abandoned merchant street of Panam Nagar and the folk art museum in Sonargaon.","img":"8d009406","mx":1920,"days":2,"km":85,"mode":"By car","cost":2229,"season":"Winter, Spring, Late autumn","stops":["lalbagh-fort","ahsan-manzil","star-mosque-dhaka","sadarghat-buriganga","panam-nagar","sonargaon-folk-art-museum"]},{"id":"kushtia-lalon-and-tagore","t":"Kushtia","s":"Lalon's akhra and Tagore's Shilaidaha","lede":"Baul songs at the shrine of Lalon in Cheuria, Tagore's riverside estate at Shilaidaha and the old Hardinge Bridge over the Padma. Best during the Lalon festival.","img":"9f148ba9","mx":1920,"days":3,"km":463,"mode":"By car","cost":5633,"season":"Late autumn, Spring","stops":["lalon-akhra-cheuria","shilaidaha-kuthibari","bheramara-hardinge-bridge","mir-mosharraf-hossain-home"]},{"id":"sylhet-tea-and-rivers","t":"Sylhet","s":"tea hills and stone rivers","lede":"Row through Ratargul's flooded forest, wade in the clear water at Jaflong and Bichanakandi, see the blue-green Lalakhal, then walk the tea gardens and rainforest of Srimangal.","img":"1d3d07b8","mx":1920,"days":6,"km":672,"mode":"By bus","cost":9459,"season":"Monsoon, Autumn","stops":["ratargul-swamp-forest","jaflong","bichanakandi","lalakhal","lawachara-national-park","srimangal-tea-gardens","madhabkunda-waterfall"]},{"id":"st-martins-island","t":"St. Martin's","s":"the coral island and Cox's Bazar","lede":"A night on Bangladesh's only coral island, with blue water and coconut palms, plus a day on the beaches of Cox's Bazar. Check current visitor rules before you go.","img":"3504ab27","mx":1920,"days":3,"km":1046,"mode":"By bus","cost":7101,"season":"Winter","stops":["coxs-bazar-beach","st-martins-island","inani-beach"]},{"id":"north-bengal-heritage-by-bike","t":"North Bengal","s":"ruins, temples and palaces by bike","lede":"Two thousand years of history on open roads: Mahasthangarh, the great vihara of Paharpur, Puthia's temples, the Natore palaces and the terracotta of Kantajew.","img":"f1cde9d9","mx":1920,"days":5,"km":758,"mode":"By bike","cost":6138,"season":"Winter, Spring","stops":["mahasthangarh","somapura-mahavihara","kantajew-temple","ramsagar","puthia-temple-complex","natore-rajbari"]},{"id":"haor-and-hills-sunamganj","t":"Sunamganj","s":"Tanguar Haor and Niladri Lake","lede":"Tanguar Haor from its edge at Tahirpur (tourist boats inside the haor are suspended for now), the blue lake at Niladri, the red soil of Barikka Tila above the Jadukata river and the shimul garden at Tahirpur.","img":"0fafd605","mx":1920,"days":3,"km":611,"mode":"By bus","cost":3305,"season":"Monsoon, Autumn","stops":["tanguar-haor","niladri-lake","barikka-tila-jadukata","shimul-bagan-tahirpur"]},{"id":"birishiri-and-mymensingh","t":"Birishiri & Mymensingh","s":"clay hills, blue lakes","lede":"The Someshwari river and the china clay hills of Bijoypur with their blue-green pools, then Shashi Lodge and the Zainul Abedin museum by the Brahmaputra.","img":"a11488ed","mx":1920,"days":3,"km":363,"mode":"By bus","cost":3476,"season":"Winter, Autumn","stops":["birisiri-someshwari","bijoypur-china-clay-hills","shashi-lodge","zainul-abedin-museum-riverside"]}];
